        styles: ["\n\n[_nghost-%COMP%] {\n    --bg-main: #f8fafc;\n    --card-bg: #ffffff;\n    --text-primary: #1e293b;\n    --text-secondary: #64748b;\n    --border-color: #e2e8f0;\n    --primary: #4f46e5;\n    --success: #10b981;\n    --danger: #ef4444;\n    --radius: 16px;\n    --shadow: 0 4px 20px rgba(0, 0, 0, 0.04);\n}\n\n\n\n.dashboard-container[_ngcontent-%COMP%] {\n    min-height: 100vh;\n    background-color: var(--bg-main);\n    padding: 30px;\n    font-family: 'Inter', -apple-system, sans-serif;\n    color: var(--text-primary);\n}\n\n\n\n.dashboard-header[_ngcontent-%COMP%] {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    background: #ffffff;\n    padding: 16px 28px;\n    border-radius: var(--radius);\n    box-shadow: var(--shadow);\n    margin-bottom: 30px;\n    border: 1px solid var(--border-color);\n}\n\n.header-logo[_ngcontent-%COMP%] {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n}\n\n.logo-icon[_ngcontent-%COMP%] { font-size: 1.8rem; }\n.header-title[_ngcontent-%COMP%] { font-size: 1.4rem; font-weight: 800; margin: 0; display: flex; align-items: center; gap: 10px; }\n.badge-app[_ngcontent-%COMP%] { font-size: 0.75rem; background: #e0e7ff; color: var(--primary); padding: 4px 10px; border-radius: 99px; font-weight: 700; }\n\n.btn-logout[_ngcontent-%COMP%] {\n    background: #f1f5f9; border: 1px solid var(--border-color); color: var(--text-primary);\n    padding: 8px 16px; border-radius: 8px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 6px; transition: all 0.2s;\n}\n.btn-logout[_ngcontent-%COMP%]:hover { background: #fee2e2; color: var(--danger); border-color: #fca5a5; }\n\n\n\n.dashboard-grid[_ngcontent-%COMP%] {\n    display: grid;\n    grid-template-columns: repeat(2, 1fr);\n    gap: 30px;\n}\n\n.full-width[_ngcontent-%COMP%] {\n    grid-column: 1 / -1;\n}\n\n\n\n.card[_ngcontent-%COMP%] {\n    background: var(--card-bg);\n    border-radius: var(--radius);\n